class DigitsStep(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    digits: Digits


class PunctuationStep(BaseModel):
    """
    strip removes General_Category P* only. Modifier letters such as U+02BB and U+02BC (gc=Lm) are letters and are never stripped.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    punctuation: Literal["strip", "keep"]


class WhitespaceStep(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    whitespace: Literal["collapse", "remove", "keep"]


type Prefix = Annotated[str, Field(min_length=1)]


class Detach(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    prefixes: Annotated[list[Prefix], Field(min_length=1)]
    minRest: Annotated[int, Field(ge=1)] = 2


class DetachStep(BaseModel):
    """
    Splits a prefix written onto the next word off from it, so the attached and the separate spellings compare alike (Arabizi elshay = el shay). A word that starts with one of the prefixes, ignoring case and by whole graphemes, and has at least minRest more graphemes, gets a space after the prefix.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    detach: Detach


class Cartouche(BaseModel):
    """
    The marks that open and close a name written with the logographs' first letters.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    open: Annotated[str, Field(min_length=1)]
    close: Annotated[str, Field(min_length=1)]


class Logographs(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    words: Annotated[
        dict[str, WordsAdditionalProperty],
        Field(
            description="Each word, as it is typed, and the logograph that writes it.", min_length=1
        ),
    ]
    cartouche: Annotated[
        Cartouche | None,
        Field(
            description="The marks that open and close a name written with the logographs' first letters."
        ),
    ] = None


class LogographsStep(BaseModel):
    """
    Words typed in a script that spells them, written as this orthography's logographs (ADR 0086): a learner can type sitelen pona as sitelen Lasina, toki for U+F196C. Each whole word (a run of letters and marks) that is a key, ignoring case, becomes its value. With `cartouche`, a name written inside one reads as the letters its logographs begin with (open, sona, olin, nasin, jan, a, close is sonja), the marks dropped, so a name typed in Latin letters compares alike. Names are read before words, so a name that spells a word (kili) becomes that word's logograph on both sides.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    logographs: Logographs


