class Contrast(BaseModel):
    """
    A set of endings, prefixes (or whole words) one letter or two apart that mean different things.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    id: Annotated[str, Field(pattern="^[a-z][a-z0-9-]*$")]
    members: Annotated[
        list[str | Members],
        Field(
            description="The members, each a meaning. An empty spelling is the word with no such affix: the bare Lebanese imperfect (shteghel) beside b-shteghel, a masculine adjective beside its feminine.",
            min_length=2,
        ),
    ]
    at: Annotated[
        Literal["end", "start"] | None,
        Field(
            description="Where the members stand: at the end of the word (endings, stacking like suffixes) or at its start (prefixes: Lebanese b-, bt-, mn- on verbs). Default end."
        ),
    ] = None
    after: Annotated[
        list[AfterItem] | None,
        Field(
            description="For prefixes: what may come before the member, a proclitic written onto the word (Arabic و 'and': وبشتغل)."
        ),
    ] = None
    inflected: Annotated[
        bool | None,
        Field(
            description="Only on words the course inflects: a word the grader is told carries a form (GradeOptions.inflected: tokens whose sense has a form KC somewhere in the course). A noun's first letter is a typo; a verb's prefix is not."
        ),
    ] = None
    forms: Annotated[
        list[Form] | None,
        Field(
            description="Only on words the course pins as one of these forms (GradeOptions.forms: the forms of the tokens a word spells): form KC ids, or how they begin (form:yiqtol matches form:yiqtol-3ms). Narrower than inflected, for a course that pins forms on nouns too: Biblical Hebrew's person prefixes are a verb's, never a noun's first letter, and its perfect endings a perfect's, never an infinitive's (ADR 0084).",
            min_length=1,
        ),
    ] = None
    note: Annotated[
        str | None,
        Field(
            description="The feedback note shown with the verdict (MF2 message feedback.note.<note>).",
            pattern="^[a-z][a-z0-9-]*$",
        ),
    ] = None


class Reports(BaseModel):
    """
    What the app sends to the report intake (ADR 0055) when a learner reports a problem: a sentence or story line they corrected (sentence_reported), or an answer they say should have been accepted or wrong (answer_reported). It carries no device, user or session id, and only the local date. A scheduled job files each report as a GitHub issue.
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )


class CorrectionSubmission(BaseModel):
    """
    A correction to a sentence, story line or word: what the device showed and what the learner changed (correction.schema.json).
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    v: Literal[1]
    kind: Literal["correction"]
    id: Annotated[
        str,
        Field(
            description="The event's id: a retried submission is the same document.",
            pattern="^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$",
        ),
    ]
    course: Annotated[str, Field(pattern="^[a-z0-9]+([.-][a-z0-9]+)*$")]
    orthography: OrthographyId
    support: Annotated[str, Field(max_length=32, min_length=1)]
    bundle: Annotated[str, Field(pattern="^[0-9a-f]{64}$")]
    item: Annotated[
        str,
        Field(
            description="The sentence id, the story id for a story line, or a word's KC id.",
            max_length=200,
            min_length=1,
        ),
    ]
    step: Annotated[
        int | None, Field(description="For a story line: its step in the story.", ge=0)
    ] = None
    shown: CorrectionFields
    correction: CorrectionFields
    note: Annotated[str | None, Field(max_length=1000)] = None
    reportedOn: Annotated[
        str, Field(description="The learner's local date.", pattern="^\\d{4}-\\d{2}-\\d{2}$")
    ]


